 \label{eq:first_order_wg_transfer_sinc}
\end{equation}
Based on
\begin{equation}
 \left|
 x\operatorname{sinc}
 \left(
 \frac{(\Delta \beta_{mm'}) x}{2}
 \right)
 \right|
 =
 \left|
 \frac{
 2\sin(\Delta\beta_{mm'} x/2)
 }{
 \Delta\beta_{mm'}
 }
 \right|
 \leq
 \frac{2}{|\Delta\beta_{mm'}|},
 \label{eq:sinc_upper_bound}
\end{equation}
where $\Delta\beta_{mm'}=\beta_{m'}-\beta_m$, we obtain
\begin{equation}
 \left|
 T_{mm'}^{(1)}(x)
