 \text{(P0):}\mathop {\max }\limits_{\left\{ {{{\bf{w}}_k}} \right\},{\bf{z}},{\bf{\Theta }},{{\bf{B}}_{\rm{t}}}} & \quad  \sum\limits_{k = 1}^K {{D_k}},\notag 
 \text{s.t.}\quad
